import type { Plugin } from "../../kernel/types";

const plugin: Plugin = {
  id: "temporary",
  name: "Temporary",
  version: "1.0.0",
  onLoad(ctx) {
    // 使用 ctx.resources.interval 管理一个计时器
    let handle: any;
    const intervalApi: any = (ctx as any).resources?.interval;
    if (intervalApi && typeof intervalApi.setInterval === "function") {
      handle = intervalApi.setInterval(() => {}, 1000);
    } else if (typeof intervalApi === "function") {
      handle = intervalApi(() => {}, 1000);
    }

    ctx.register({
      kind: "tool",
      tool: {
        name: "lifetime_value",
        version: "1.0.0",
        description: "返回固定值 9",
        permissions: { capabilities: [] },
        sideEffect: "pure",
        parameters: { type: "object", properties: {}, additionalProperties: false },
        outputSchema: { type: "object", properties: { ok: { type: "boolean" }, data: { type: "number" } }, required: ["ok", "data"] },
        async handler(_args: any, _tctx: any) {
          return { ok: true, data: 9 };
        },
      },
    });

    // 卸载时清理计时器
    ctx.onUnload?.(() => {
      if (!handle) return;
      if (intervalApi && typeof intervalApi.clearInterval === "function") {
        intervalApi.clearInterval(handle);
      } else if (handle && typeof handle.clear === "function") {
        handle.clear();
      } else if (handle && typeof handle.dispose === "function") {
        handle.dispose();
      }
    });
  },
};

export default plugin;

